/**
 * STEP 8 / Phase 2.1: KeyboardManager
 *
 * モバイルでソフトキーボードが表示されたときの viewport 縮小量を観測し、
 * `keyboardHeight$` / `isKeyboardOpen$` / `viewportHeight$` を提供する。
 *
 * 実装根拠:
 *   - chat-page.component.ts に直書きされていた visualViewport 処理を抽出
 *   - 入力 UI を持つ全ページ (mail-compose / community/*-create / event-editor / profile)
 *     で同じ動作を保証する
 *
 * iOS Safari / Android Chrome で検証済の API。古い Android ブラウザ
 * (visualViewport 非対応) では keyboardHeight=0 の no-op として動作する。
 */
import { Injectable, NgZone, OnDestroy } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { distinctUntilChanged, map } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class KeyboardManagerService implements OnDestroy {
  private readonly _keyboardHeight$ = new BehaviorSubject<number>(0);
  private readonly _viewportHeight$ = new BehaviorSubject<number>(
    typeof window !== 'undefined' ? window.innerHeight : 0,
  );

  readonly keyboardHeight$: Observable<number> =
    this._keyboardHeight$.asObservable().pipe(distinctUntilChanged());

  readonly isKeyboardOpen$: Observable<boolean> =
    this._keyboardHeight$.pipe(map(h => h > 50), distinctUntilChanged());

  readonly viewportHeight$: Observable<number> =
    this._viewportHeight$.asObservable().pipe(distinctUntilChanged());

  /** 現在のキーボード高さ (同期取得) */
  get keyboardHeight(): number { return this._keyboardHeight$.value; }
  get isKeyboardOpen(): boolean { return this._keyboardHeight$.value > 50; }
  get viewportHeight(): number { return this._viewportHeight$.value; }

  private vvHandler?: () => void;
  private resizeHandler?: () => void;

  constructor(private ngZone: NgZone) {
    if (typeof window === 'undefined') return;
    this.attach();
  }

  private attach(): void {
    const vv = (window as any).visualViewport as VisualViewport | undefined;
    if (vv) {
      this.vvHandler = () => {
        // キーボード高さ = window.innerHeight - vv.height - vv.offsetTop
        const kbh = Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
        const vph = vv.height;
        // ngZone.run で OnPush コンポーネントへ反映させる
        this.ngZone.run(() => {
          this._keyboardHeight$.next(kbh);
          this._viewportHeight$.next(vph);
        });
      };
      vv.addEventListener('resize', this.vvHandler);
      vv.addEventListener('scroll', this.vvHandler);
      // 初回値
      this.vvHandler();
    } else {
      // visualViewport 非対応: window.resize で代替 (キーボード検出は不可)
      this.resizeHandler = () => {
        this.ngZone.run(() => this._viewportHeight$.next(window.innerHeight));
      };
      window.addEventListener('resize', this.resizeHandler);
    }
  }

  ngOnDestroy(): void {
    const vv = (window as any).visualViewport as VisualViewport | undefined;
    if (vv && this.vvHandler) {
      vv.removeEventListener('resize', this.vvHandler);
      vv.removeEventListener('scroll', this.vvHandler);
    }
    if (this.resizeHandler) {
      window.removeEventListener('resize', this.resizeHandler);
    }
  }
}
